SELECT id, session_id, event_type, page, event_time, duration_sec, COUNT(duration_sec) OVER w_ordered event_time_period_count_duration_sec, LAG(duration_sec, 1) OVER w_recent prev_duration_sec, LAST_VALUE(duration_sec, TRUE) OVER w_ordered_2 last_known_duration_sec, NTILE(10) OVER (PARTITION BY YEAR(event_time), session_id ORDER BY duration_sec, id) duration_sec_bucket FROM web_events WINDOW w_ordered AS (PARTITION BY DATE_TRUNC('YEAR', event_time), session_id), w_recent AS (ORDER BY event_time, id), w_ordered_2 AS (PARTITION BY page ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
